INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62301623', 62301623, 'analyze_legacy', 'Mahkamah Agung', 'central', 'MAHKAMAH SYARIYAH ACEH01', 'Sewa Mesin Fotocopy Mahkamah Syar\'iyah Aceh', 'Jasa Lainnya', 'E-Purchasing', 'Aceh, Banda Aceh (Kota)', 1650000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 25, UNIT, @ 66000000 )', '1. Sewa Mesin Fotocopy ( 25, UNIT, @ 66000000 );', 'a. Penyedia adalah yang sudah terkualifikasi dengan memiliki NIB Berbasis Risiko dengan Kode KBLI 77394 (Aktivitas Penyewaan dan Sewa Guna Usaha tanpa hak opsi mesin kantor dan peralatannya dan KBLI 82190 (Aktivitas Fotokopi penyiapan dokumen dan aktivitas khusus penunjang kantor lainnya, dengan kondisi kedua KBLI tersebut harus terpenuhi semua. b. Memiliki pengalaman minimal 10 Kontrak selama kurun waktu 3 tahun terakhir pengalaman Barang/Jasa Lainnya yang sesuai dengan kebutuhan pekerjaan yang akan dilaksanakan dengan nilai pengalaman paling sedikit sama dengannilai HPS; c. Kinerja penyedia ditetapkan berdasarkan prestasi pekerjaan sebelumnya, dengan kriteria kinerja minimal baik dan Penyedia belum pernah mendapatkan surat teguran/surat peringatan satu (SP 1) yang ditandatangani oleh Pejabat Pembuat Komitmen; d. Melampirkan surat dari pihak pemilik mesin fotokopi sesuai dengan merk, type dan spesifikasi teknis sejumlah minimal 800 unit disertai dengan surat notaris atas kepemilikan tersebut dengan kondisi semua mesin dalam kondisi baik dan berjalan semua fungsi sebagaimana mestinya; e. Melampirkan surat lampiran Device Statistic dengan minimal keluaran atau pembuatan mesin tahun 2022 disertai Nomor Rangka atau Serial Number/SN Mesin; f. Melampirkan brosur dan membuat surat keterangan menyediakan mesin fotokopi yang ditawarkan sesuai spesifikasi teknis. g. Melampirkan surat keterangan kesanggupan ketersediaan bahan pakai berupa Tonner, drum dan sparepart mesin yang ditawarkan sesuai dengan spesifikasi teknis. h. Melampirkan surat keterangan kesanggupan memberikan pelayanan service, seperti pergantian suku cadang dan Tonner Black (Hitam) selama masa kontrak tanpa ada batasan pemakaian dan menyiapakan 1 Tonner Black (Hitam) dan 1 (Satu) Tonner Cartridge Color (Warna) cadangan di masing- masing satuan kerja untuk menjaga agar pelayanan tidak terganggu. i. Memiliki jaringan kerja minimal 1 (satu) kantor layanan di ibu kota provinsi dengan mencantumkan alamat kantor layanan dan nomor telepon yang bisa dihubungi. j. Memiliki minimal 3 teknisi bersertifikasi di setiap provinsi yang di buktikan dengan KTP dan Sertifikat keterampilan teknis. k. Melampirkan surat kesanggupan menyediakan sendiri pelayanan call center atau hotline selama 24 jam dengan tenaga operator minimal 2 orang; l. Melampirkan proposal alur pelayanan service dari satker kantor pengadilan seluruh Indonesia ke hotline, yang meliputi metodologi pelaksanaan pekerjaan, timeline dalam bentuk flow chart, struktur organisasi untuk layanan menyediakan perbaikan mesin fotokopi yang rusak sampai akhirnya bisa berjalan sebagaimana mestinya; m. Melampirkan proposal bahwa tipe mesin yang ditawarkan mempunyai solusi dan kemampuan pengecekan secara online (menggunakan Cloud Fleet Management berbasis internet cloud dan web) secara berkala untuk mengetahui ketersediaan Tonner Cafridge dan Drum Catridge, artinya Tonner dan Drum catridge harus selalu terjaga ketersediaannya untuk setiap mesin fotokopi.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 400620);
