INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62303974', 62303974, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Koperasi Koperasi Desa/Kelurahan Merah Putih', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup kegiatan untuk Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Koperasi Desa/Kelurahan Merah Putih adalah sebagai berikut. 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang KDKMP; 2. Menyusun analisis MRPN pada bidang KDKMP sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan bidang KDKMP pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang KDKMP.', 'Keluaran yang dihasilkan dari pengadaan Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Koperasi Desa/Kelurahan Merah Putih untuk mendukung kegiatan Pengendalian, Evaluasi, dan Manajemen Risiko Pembangunan pada Bidang Polhukhankam, Tata Kelola Pemerintahan, Kesejahteraan dan Pemerataan adalah Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang KDKMP dengan waktu penyelesaian 6 (enam) termin selama 12 (dua belas) bulan, di mana 1 termin pelaporan dilaksanakan dalam jangka waktu 2 bulan. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut. No. Periode Keluaran per Termin 1 Termin 1 Laporan pengembangan metodologi sinergi MRPN dalam pengendalian dan evaluasi Bidang KDKMP 2 Termin 2 Laporan analisis MRPN dalam evaluasi Ex-Ante Bidang KDKMP 3 Termin 3 Laporan analisis MRPN untuk pengendalian TW I Bidang KDKMP 4 Termin 4 Laporan analisis MRPN untuk pengendalian TW II Bidang KDKMP 5 Termin 5 Laporan analisis MRPN untuk pengendalian TW III Bidang KDKMP 6 Termin 6 Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang KDKMP', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 402655);
