INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62352630', 62352630, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN KEPEGAWAIAN DAERAH', 'Belanja Jasa Konsultasi Computer Operator/ Typist Kegiatan Pengelolaan dan Penataan Arsip Pegawai', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 335500000, 'November 2025', 'APBD', 1, 1, '5 (orang) x 11 (bulan)', '1. Mengoperasikan komputer untuk pencarian arsip, daftar arsip, register arsip, dan dokumen administrasi lainnya. 2. Melakukan input data arsip ke dalam aplikasi pengelolaan arsip (manual atau digital). 3. Menyusun dan memperbarui daftar inventaris arsip (daftar arsip aktif, inaktif, dan permanen). 4. Melakukan labeling, penomoran, dan pemberian kode klasifikasi arsip sesuai pedoman klasifikasi. 5. Menata arsip dalam folder, map, boks arsip, atau rak penyimpanan sesuai sistem penataan (lemari, deret, baris, kolom, nomor urut). 6. Melakukan pengecekan kesesuaian arsip dengan daftar dokumen (verifikasi data). 7.Membantu proses peminjaman dan pengembalian arsip (arsip dynamic record center). 8. Menjaga keteraturan, kebersihan, dan keamanan ruang penyimpanan arsip. 9. Melakukan penyusunan laporan kegiatan pengelolaan arsip secara berkala (harian/mingguan/bulanan). 10. Menjaga kerahasiaan dan integritas informasi arsip selama proses penataan dan pengolahan.', '1. Pendidikan : Minimal SMA/Sederajat 2. Mampu mengoperasikan perangkat Komputer dan alat pindai/scanner dokumen 3, Sehat Jasmani dan Rohani 4. Mampu bekerja sesuai dengan ketentuan dan aturan yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 402715);
