INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64692594', 64692594, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA MOROTAI 04', 'Belanja Pos Bantuan Hukum', 'Jasa Lainnya', 'Penunjukan Langsung', 'Maluku Utara, Halmahera Utara (Kab.)', 10000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '100 Orang', 'Penyedia jasa Pos Bantuan Hukum bertanggung jawab untuk memberikan layanan bantuan hukum secara cuma-cuma kepada masyarakat pencari keadilan yang tidak mampu di lingkungan Pengadilan Agama. Ruang lingkup pekerjaan meliputi: Pemberian Informasi Hukum Memberikan informasi terkait prosedur berperkara, persyaratan administrasi, serta hak dan kewajiban para pihak di pengadilan. Konsultasi dan Advis Hukum Memberikan konsultasi serta pertimbangan hukum kepada penggugat/pemohon maupun tergugat/termohon sesuai ketentuan peraturan perundang-undangan. Penyusunan Dokumen Hukum Membantu pembuatan surat gugatan, permohonan, atau dokumen hukum lain yang diperlukan dalam proses berperkara. Pelayanan bagi Masyarakat Tidak Mampu Memberikan layanan bantuan hukum secara gratis bagi masyarakat yang tidak mampu secara ekonomi maupun hukum dalam menjalankan proses di pengadilan. Pelaksanaan Layanan Sesuai Pedoman Mahkamah Agung Pelayanan dilakukan berdasarkan pedoman pemberian layanan hukum bagi masyarakat tidak mampu sebagaimana diatur dalam Peraturan Mahkamah Agung dan Surat Edaran Mahkamah Agung. Operasional Posbakum Melaksanakan layanan pada ruang yang disediakan pengadilan selama tahun anggaran berjalan sesuai DIPA.', 'Spesifikasi Pekerjaan Ketentuan Umum Penyedia wajib menyelenggarakan layanan Pos Bantuan Hukum bagi masyarakat pencari keadilan yang tidak mampu pada Pengadilan Agama sesuai dengan ketentuan Peraturan Mahkamah Agung tentang layanan hukum bagi masyarakat tidak mampu serta peraturan perundang-undangan terkait. Kualifikasi Personel Penyedia menyediakan petugas minimal 1 (satu) orang setiap hari layanan. Petugas merupakan Advokat, atau Sarjana Hukum/Sarjana Syariah yang memiliki kompetensi di bidang hukum keluarga dan prosedur berperkara di Pengadilan Agama. Memiliki kemampuan komunikasi yang baik serta mampu memberikan pelayanan prima kepada masyarakat. Berpakaian rapi dan sopan serta menjaga etika profesi. Jenis Layanan Penyedia wajib memberikan layanan meliputi: Pemberian informasi hukum terkait tata cara berperkara. Konsultasi dan advis hukum. Penyusunan dokumen hukum seperti surat gugatan, permohonan, jawaban, replik, duplik, dan dokumen lain yang diperlukan. Pengarahan kepada pihak berperkara mengenai kelengkapan administrasi. Waktu dan Tempat Pelayanan Layanan dilaksanakan pada ruang Posbakum yang telah disediakan oleh Pengadilan Agama. Jam layanan mengikuti hari dan jam kerja kantor Pengadilan Agama. Pelayanan diberikan selama tahun anggaran berjalan sesuai kontrak. Standar Pelayanan Layanan diberikan secara gratis (prodeo) kepada masyarakat yang memenuhi kriteria tidak mampu. Penyedia wajib memberikan pelayanan secara cepat, ramah, non-diskriminatif, dan profesional. Menjamin kerahasiaan data dan informasi para pihak. Tidak diperkenankan meminta atau menerima imbalan dalam bentuk apa pun dari penerima layanan. Output Pekerjaan Terselenggaranya layanan bantuan hukum bagi masyarakat tidak mampu. Tersusunnya dokumen hukum sesuai kebutuhan penerima layanan. Tersedianya laporan pelaksanaan layanan secara berkala (bulanan atau triwulanan) kepada Pejabat Pembuat Komitmen (PPK) atau pejabat yang ditunjuk. Pelaporan dan Evaluasi Penyedia wajib membuat laporan jumlah penerima layanan, jenis layanan, serta permasalahan yang dihadapi. Bersedia dilakukan monitoring dan evaluasi oleh Pengadilan Agama untuk menjamin kualitas layanan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 404570);
