INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62306515', 62306515, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian Pembangunan Tiga Juta Rumah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup kegiatan Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian Pembangunan Bidang Tiga Juta Rumah adalah sebagai berikut: 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang tiga juta rumah; 2. Menyusun analisis MRPN pada bidang tiga juta rumah sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan bidang tiga juta rumah pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang tiga juta rumah.', 'Keluaran yang dihasilkan dari pengadaan Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian Pembangunan Bidang Tiga Juta Rumah untuk mendukung Kegiatan Pengendalian, Evaluasi dan Manajemen Risiko Pembangunan Bidang Polhukhankam, Tata Kelola Pemerintahan, Kesejahteraan dan Pemerataan adalah Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Tiga Juta Rumah dengan waktu penyelesaian 6 (enam) termin selama 12 (dua belas) bulan. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: No Periode Keluaran per Termin 1 Termin I Laporan pengembangan metodologi sinergi MRPN dalam pengendalian dan evaluasi Bidang Tiga Juta Rumah 2 Termin II Laporan analisis MRPN dalam evaluasi Ex-Ante Bidang Tiga Juta Rumah 3 Termin III Laporan analisis MRPN untuk pengendalian TW I Bidang Tiga Juta Rumah 4 Termin IV Laporan analisis MRPN untuk pengendalian TW II Bidang Tiga Juta Rumah 5 Termin V Laporan analisis MRPN untuk pengendalian TW III Bidang Tiga Juta Rumah 6 Termin VI Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Tiga Juta Rumah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 404955);
