INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62353378', 62353378, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Layanan Ekstranet pada PPATK T.A. 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 400000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Tersedianya: - Layanan Ekstranet VPN IP MPLS 5 Mbps KPK dan Kejaksaan Agung dan Layanan Ekstranet VPN IP MPLS 5 Mbps Dukcapil', '1. Spesifikasi Teknis Layanan Ekstranet MPLS VPN ke KPK dan Kejaksaan Agung: a. Jenis Layanan • MPLS‐ VPN (Multi Protocols Label Switching – Virtual Private Network); • Bandwidth sebesar 5 Mbps dengan rasio CIR (Commited Information Rate) 1:1; • Layanan extranet Layer 3 (network / routing); • Menghubungkan PPATK dengan instansi mitra KPK dan Kejaksaan Agung yang menggunakan layanan serupa yang disediakan oleh ISP ini juga; b. Interface dan tipe konektor yang terhubung ke perangkat CE (customer edge) PPATK adalah 1G RJ‐45; c. Perangkat aktif milik ISP yang dipasang di PPATK dan digunakan untuk layanan ini harus memiliki redundant power supply; d. Service Level Agreement (SLA) • Uptime ≥ 99,9% per bulan (dari jumlah bandwidth yang disewa) • Response time (corrective maintenance) max 1 jam setelah laporan e. Dukungan Teknis • NOC 24x7 dengan kontak eskalasi • Kunjungan technical support saat dibutuhkan sepanjang 24x7 • Layanan pengawasan gangguan secara dini (preventive support); f. Pemantauan • Portal pemantauan online 24x7 untuk pengguna g. Laporan Rutin • Wajib disampaikan secara bulanan melalui email • Berisi setidaknya: i. Statistik dan/atau grafik penggunaan bandwidth ii. Laporan jumlah dan persentase uptime dan downtime iii. Log insiden dan penanganan iv. History gangguan (planned/unplanned) h. Sanggup menyediakan kenaikan bandwidth temporer (bandwidth-on-demand) minimal 200% dari bandwidth yang sedang disewa sesuai dengan prosedur yang berlaku di ISP dan menyediakan teknisi on-site ketika bandwidth-on demand berlangsung. 2. Spesifikasi Teknis Layanan Ekstranet MPLS VPN ke Dukcapil: a. Jenis Layanan • MPLS‐ VPN (Multi Protocols Label Switching – Virtual Private Network); • Bandwidth sebesar 5 Mbps dengan rasio CIR (Commited Information Rate) 1:1; • Layanan extranet Layer 3 (network / routing); • Menghubungkan PPATK dengan instansi mitra KPK dan Kejaksaan Agung yang menggunakan layanan serupa yang disediakan oleh ISP ini juga; b. Interface dan tipe konektor yang terhubung ke perangkat CE (customer edge) PPATK adalah 1G RJ‐45; c. Perangkat aktif milik ISP yang dipasang di PPATK dan digunakan untuk layanan ini harus memiliki redundant power supply; d. Service Level Agreement (SLA) • Uptime ≥ 99,9% per bulan (dari jumlah bandwidth yang disewa) • Response time (corrective maintenance) max 1 jam setelah laporan e. Dukungan Teknis • NOC 24x7 dengan kontak eskalasi • Kunjungan technical support saat dibutuhkan sepanjang 24x7 • Layanan pengawasan gangguan secara dini (preventive support); f. Pemantauan • Portal pemantauan online 24x7 untuk pengguna g. Laporan Rutin • Wajib disampaikan secara bulanan melalui email • Berisi setidaknya: i. Statistik dan/atau grafik penggunaan bandwidth ii. Laporan jumlah dan persentase uptime dan downtime iii. Log insiden dan penanganan iv. History gangguan (planned/unplanned) h. Sanggup menyediakan kenaikan bandwidth temporer (bandwidth-on-demand) minimal 200% dari bandwidth yang sedang disewa sesuai dengan prosedur yang berlaku di ISP dan menyediakan teknisi on-site ketika bandwidth-on demand berlangsung.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 406731);
